begin;
set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table tecnica_test(actor uuid,company_id uuid,order_id uuid,pos_id uuid,contenuto jsonb);
insert into tecnica_test select sp.user_id,sp.company_id,o.id,gen_random_uuid(),null from public.staff_permissions sp join public.orders o on o.company_id=sp.company_id where sp.can_view_sicurezza_cantiere and not sp.sola_lettura limit 1;
grant select on tecnica_test to authenticated;
do $$begin if not exists(select 1 from tecnica_test) then raise exception 'Azienda di prova assente';end if;end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from tecnica_test;
update tecnica_test set contenuto='{"versione_modello": 1, "versione_controlli": 2, "versione_tecnica": 1, "formazione": [], "lavorazioni": [{"id": "l1", "titolo": "TEST SCHEDA TECNICA", "tecnica": {"area": "TEST area", "interferenze": "TEST interferenze", "condizioni_avvio": "TEST condizioni_avvio", "sospensione": "TEST sospensione", "emergenze": "TEST emergenze", "prima": "TEST prima", "durante": "TEST durante", "dopo": "TEST dopo", "riesaminata": true, "attrezzature_previste": "si", "motivo_senza_attrezzature": "", "rischi": [{"id": "r1", "pericolo": "TEST pericolo", "esposti": "TEST esposti", "situazione": "TEST situazione", "valutazione_iniziale": "TEST valutazione_iniziale", "misure_collettive": "TEST misure_collettive", "misure_organizzative": "TEST misure_organizzative", "dpi": "TEST dpi", "valutazione_residua": "TEST valutazione_residua", "riferimento": "TEST riferimento"}], "attrezzature": [{"id": "a1", "nome": "TEST nome", "identificativo": "TEST identificativo", "impiego": "TEST impiego", "controlli_preuso": "TEST controlli_preuso", "manuale_riferimento": "TEST manuale_riferimento", "formazione_addestramento": "TEST formazione_addestramento"}]}}]}'::jsonb;

create temporary table fonti_test(d1 uuid default gen_random_uuid(),d2 uuid default gen_random_uuid(),d3 uuid default gen_random_uuid(),d4 uuid default gen_random_uuid(),d5 uuid default gen_random_uuid(),fase uuid default gen_random_uuid(),fase2 uuid default gen_random_uuid(),sub uuid default gen_random_uuid(),altro uuid,prova jsonb,emissione jsonb,manifest jsonb);
insert into fonti_test(altro) select id from public.orders where company_id=(select company_id from tecnica_test) and id<>(select order_id from tecnica_test) and deleted_at is null limit 1;
grant select on fonti_test to authenticated;
grant select on tecnica_test,fonti_test to service_role;
insert into public.subappaltatori_sicurezza(id,company_id,order_id,ragione_sociale) select t.sub,f.company_id,f.order_id,'TEST FONTI ESTERNA' from fonti_test t cross join tecnica_test f;
insert into public.order_work_phases(id,company_id,order_id,name,position)select t.fase,f.company_id,f.order_id,'TEST FONTI FASE',998 from fonti_test t cross join tecnica_test f union all select t.fase2,f.company_id,f.order_id,'TEST FONTI ALTRA FASE',999 from fonti_test t cross join tecnica_test f;
insert into storage.objects(bucket_id,name) select 'fascicoli-cantiere',f.company_id::text||'/'||v.id::text||'/tecnico-test.pdf' from tecnica_test f cross join fonti_test t cross join lateral(values(t.d1),(t.d2),(t.d3),(t.d4),(t.d5))v(id);
insert into public.sicurezza_fascicolo(id,company_id,order_id,subappaltatore_id,fase_id,tipo,titolo,file_path,file_name,stato,revisione,data_rilascio)
select v.id,f.company_id,v.ordine,v.sub,v.fase,v.tipo,'TEST FONTE TECNICA',f.company_id::text||'/'||v.id::text||'/tecnico-test.pdf','tecnico-test.pdf','ricevuto','1','2026-10-01' from tecnica_test f cross join fonti_test t cross join lateral(values(t.d1,f.order_id,null::uuid,null::uuid,'attrezzatura'),(t.d2,f.order_id,null::uuid,t.fase2,'dvr'),(t.d3,f.order_id,t.sub,null::uuid,'attrezzatura'),(t.d4,f.order_id,null::uuid,null::uuid,'durc'),(t.d5,t.altro,null::uuid,null::uuid,'attrezzatura'))v(id,ordine,sub,fase,tipo);
update public.sicurezza_fascicolo set stato='verificato' where id in(select d1 from fonti_test union all select d2 from fonti_test union all select d5 from fonti_test);
update tecnica_test set contenuto=contenuto||jsonb_build_object('versione_fonti_tecniche',1,'opera',jsonb_build_object('data_inizio','2026-11-01','data_fine','2026-11-30'));
update tecnica_test set contenuto=jsonb_set(contenuto,'{lavorazioni,0,fase_id}',to_jsonb((select fase::text from fonti_test)));
update tecnica_test set contenuto=jsonb_set(jsonb_set(contenuto,'{lavorazioni,0,tecnica,rischi,0,fonti}',jsonb_build_object('modalita','documenti','motivazione','','documenti',jsonb_build_array((select public.pos_documento_tecnico_foto(e) from public.sicurezza_fascicolo e where e.id=(select d1 from fonti_test))))),'{lavorazioni,0,tecnica,attrezzature,0,fonti}',jsonb_build_object('modalita','documenti','motivazione','','documenti',jsonb_build_array((select public.pos_documento_tecnico_foto(e) from public.sicurezza_fascicolo e where e.id=(select d1 from fonti_test)))));
insert into public.pos_documents(id,company_id,order_id,tipo_lavori,indirizzo_cantiere,status,revisione,contenuto,iter,updated_at) select pos_id,company_id,order_id,'TEST FONTI TECNICHE ROLLBACK','Indirizzo sintetico','bozza',0,contenuto,'{}',clock_timestamp() from tecnica_test;
set local role authenticated;
do $$declare f record;t record;q jsonb;begin select * into f from tecnica_test;select * into t from fonti_test;
 begin perform public.pos_documenti_tecnici_quadro(gen_random_uuid(),f.order_id);raise exception 'ASSERT: altra azienda';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
 begin perform public.pos_documenti_tecnici_quadro(f.company_id,f.order_id);raise exception 'ASSERT: soggetto privo di accesso';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f.actor,'role','authenticated')::text,true);
 q:=public.pos_documenti_tecnici_quadro(f.company_id,f.order_id);
 if jsonb_array_length(q->'documenti')<>2 or q::text like '%file_path%' or exists(select 1 from jsonb_array_elements(q->'documenti') x where x->>'id' not in (t.d1::text,t.d2::text) or x->'confermata'<>'false'::jsonb) then raise exception 'ASSERT: selezione amplia ambito o conferma in automatico';end if;
 if public.pos_documento_tecnico_apri(f.company_id,f.order_id,t.d1,(select x->>'impronta' from jsonb_array_elements(q->'documenti')x where x->>'id'=t.d1::text)) is null then raise exception 'ASSERT: apertura fonte disponibile negata';end if;
 begin perform public.pos_documento_tecnico_apri(f.company_id,f.order_id,t.d3,'nonimporta');raise exception 'ASSERT: documento esterno apribile';exception when insufficient_privilege then null;end;
 begin perform public.pos_fonti_tecniche_emissione(f.pos_id,f.actor);raise exception 'ASSERT: client risolve path emissione';exception when insufficient_privilege then null;end;
 begin update public.pos_documents set contenuto=contenuto-'versione_fonti_tecniche' where id=f.pos_id;raise exception 'ASSERT: downgrade';exception when serialization_failure then null;end;
end$$;
reset role;
do $$declare f record;t record;q jsonb;c jsonb;e public.sicurezza_fascicolo;begin select * into f from tecnica_test;select * into t from fonti_test;
 q:=public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,f.contenuto);
 if jsonb_array_length(q->'collegamenti')<>2 or jsonb_array_length(q->'allegati')<>1 or q->'allegati'->0->>'evidenza_id'<>t.d1::text then raise exception 'ASSERT: riuso o deduplicazione errati';end if;
 begin perform public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,rischi,0,fonti,documenti,0,titolo}','"Falso"'));raise exception 'ASSERT: fotografia alterata';exception when serialization_failure then null;end;
 begin perform public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,rischi,0,fonti,documenti,0,confermata}','false'));raise exception 'ASSERT: pertinenza non confermata';exception when serialization_failure then null;end;
 select * into e from public.sicurezza_fascicolo where id=t.d2;
 begin perform public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,rischi,0,fonti,documenti,0}',public.pos_documento_tecnico_foto(e)));raise exception 'ASSERT: altra fase';exception when raise_exception then if sqlerrm not like 'Documento tecnico non applicabile%' then raise;end if;end;
 select * into e from public.sicurezza_fascicolo where id=t.d5;
 begin perform public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,rischi,0,fonti,documenti,0}',public.pos_documento_tecnico_foto(e)));raise exception 'ASSERT: altra commessa';exception when raise_exception then if sqlerrm not like 'Documento tecnico non pertinente%' then raise;end if;end;
 begin
  update public.sicurezza_fascicolo set stato='integrazione' where id=t.d1;update public.sicurezza_fascicolo set applicabile_al='2026-11-15' where id=t.d1;update public.sicurezza_fascicolo set stato='verificato' where id=t.d1;select * into e from public.sicurezza_fascicolo where id=t.d1;
  c:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,rischi,0,fonti,documenti,0}',public.pos_documento_tecnico_foto(e));c:=jsonb_set(c,'{lavorazioni,0,tecnica,attrezzature,0,fonti,documenti,0}',public.pos_documento_tecnico_foto(e));
  begin perform public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,c);raise exception 'ASSERT: periodo parziale';exception when raise_exception then if sqlerrm not like 'Documento tecnico non applicabile%' then raise;end if;end;
  raise exception 'ROLLBACK SUBTEST';exception when raise_exception then if sqlerrm<>'ROLLBACK SUBTEST' then raise;end if;end;
 c:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,rischi,0,fonti}',jsonb_build_object('modalita','testo_pos','motivazione','TEST valutazione propria nel POS, nessun originale esterno','documenti','[]'::jsonb));
 c:=jsonb_set(c,'{lavorazioni,0,tecnica,attrezzature,0,fonti}',jsonb_build_object('modalita','non_applicabile','motivazione','TEST motivazione da validare','documenti','[]'::jsonb));
 if jsonb_array_length(public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,c)->'allegati')<>0 then raise exception 'ASSERT: dichiarazione testuale diventa allegato';end if;
 begin perform public.pos_fonti_tecniche_verifica(f.company_id,f.order_id,jsonb_set(c,'{lavorazioni,0,tecnica,rischi,0,fonti,motivazione}','""'));raise exception 'ASSERT: dichiarazione priva di motivo';exception when raise_exception then if sqlerrm not like 'Motiva la fonte%' then raise;end if;end;
 update fonti_test set prova=q;
end$$;
-- Simulated object metadata only: original byte storage is covered separately in service tests.
update fonti_test t set emissione=public.pos_prenota_emissione(f.pos_id,f.actor,p.updated_at,null) from tecnica_test f join public.pos_documents p on p.id=f.pos_id;
update fonti_test t set manifest=jsonb_build_object('emissioneId',t.emissione->>'id','companyId',f.company_id,'posId',f.pos_id,'revisione',0,'origine','approvazione_corrente','file',(select jsonb_agg(jsonb_build_object('nome',n,'path',f.company_id::text||'/'||(t.emissione->>'id')||'/'||(t.emissione->>'token')||'/'||n,'sha256',repeat('a',64),'dimensione',1))from unnest(array['POS.pdf','modello.html','fonti.json'])n))from tecnica_test f;
insert into storage.objects(bucket_id,name)select 'pos-emissioni',f.company_id::text||'/'||(t.emissione->>'id')||'/'||(t.emissione->>'token')||'/'||n from fonti_test t cross join tecnica_test f cross join unnest(array['POS.pdf','modello.html','fonti.json','manifest.json','fascicolo.zip','TECNICO.pdf'])n;
do $$declare f record;t record;begin select * into f from tecnica_test;select * into t from fonti_test;
 begin perform public.pos_completa_emissione((t.emissione->>'id')::uuid,(t.emissione->>'token')::uuid,f.actor,'TEST',t.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: fonti nel manifest mancanti';exception when raise_exception then if sqlerrm<>'Il pacchetto non conserva le fonti tecniche riesaminate' then raise;end if;end;
 t.manifest:=t.manifest||jsonb_build_object('fonti_tecniche',jsonb_build_object('versione',1,'collegamenti',t.prova->'collegamenti'));
 begin perform public.pos_completa_emissione((t.emissione->>'id')::uuid,(t.emissione->>'token')::uuid,f.actor,'TEST',t.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: originale tecnico non dichiarato';exception when raise_exception then if sqlerrm<>'Documento tecnico specifico non conservato nel pacchetto' then raise;end if;end;
 update fonti_test set manifest=t.manifest||jsonb_build_object('file',(t.manifest->'file')||jsonb_build_array(jsonb_build_object('nome','TECNICO.pdf','path',f.company_id::text||'/'||(t.emissione->>'id')||'/'||(t.emissione->>'token')||'/TECNICO.pdf','sha256',repeat('d',64),'dimensione',1,'ruolo','allegato','tipo','evidenza_tecnica','evidenza_id',t.d1,'impronta_metadati',t.prova->'allegati'->0->>'impronta','fonte',jsonb_build_object('bucket','fascicoli-cantiere','path',t.prova->'allegati'->0->>'path'))));
 begin
  update public.sicurezza_fascicolo set note='TEST MODIFICA NELLA STESSA TRANSAZIONE' where id=t.d1;
  begin perform public.pos_completa_emissione((t.emissione->>'id')::uuid,(t.emissione->>'token')::uuid,f.actor,'TEST',(select manifest from fonti_test),repeat('b',64),repeat('c',64));raise exception 'ASSERT: fonte modificata durante emissione';exception when serialization_failure then null;end;
  raise exception 'ROLLBACK SUBTEST FONTE';exception when raise_exception then if sqlerrm<>'ROLLBACK SUBTEST FONTE' then raise;end if;end;
end$$;
set local role service_role;
select public.pos_completa_emissione((t.emissione->>'id')::uuid,(t.emissione->>'token')::uuid,f.actor,'TEST FONTI',t.manifest,repeat('b',64),repeat('c',64)) from fonti_test t cross join tecnica_test f;
reset role;
do $$begin if not exists(select 1 from public.pos_documents where id=(select pos_id from tecnica_test) and status='approvato')then raise exception 'ASSERT: emissione corretta non completa';end if;end$$;
select 'PASS fonti tecniche: scope, versioni, periodo, dichiarazioni, originali e finalizzazione atomica (solo metadati)' as risultato;
rollback;
